 * @param {string} environmentId
 * @returns {Promise<string[]>}
 */
export async function getExistingLocaleCodes(client, environmentId) {
  const { items } = await client.locale.getMany({ environmentId, query: { limit: 100 } });
  return items.map((l) => l.code);
}

/**
 * Parses a `--target <env>` flag from argv, defaulting to 'dev'. Exits the process with a
 * descriptive message if the flag is present but has no value following it — extracted verbatim
 * from the three seedXUiCopy.mjs scripts (SFCC-742's seedLoginDrawerUiCopy.mjs first, then
 * SFCC-831/689's seedRegionalPromptUiCopy.mjs and seedDrawerCloseUiCopy.mjs copied it), which had
 * each independently reimplemented this exact logic.
 * @param {string[]} [args]
 * @returns {string}
 */
export function resolveTarget(args = process.argv.slice(2)) {
  const i = args.indexOf('--target');
  const rawTarget = i !== -1 ? args[i + 1] : null;
  if (rawTarget === undefined) {
    // --target flag was present but no value followed it
    console.error('Error: --target requires a value, e.g. --target dev');
    process.exit(1);
  }
  return rawTarget ?? 'dev';
}

/**
 * Seeds a list of `uiCopy` entries into a target Contentful environment: creates and publishes
 * any that don't yet exist, publishes any that exist only as an unpublished draft AND whose
 * title/value/description already match this script's data, and skips any that are already
 * published. Safe to re-run when a found draft's content agrees with `entries` — when it
 * doesn't (a prior interrupted run, a manual edit in Contentful's UI, or `entries` changing
 * after a stale draft was left behind), that entry is deliberately NOT published: the mismatch
 * is logged via {@link log.error} and, once every entry has been processed, an Error is thrown
 * listing every conflicting key so the overall run fails loudly instead of silently publishing
 * content the caller didn't ask for. A conflict on one key does not stop other, non-conflicting
 * entries in the same batch from being created, published, or skipped normally. Extracted
 * verbatim from the same three scripts {@link resolveTarget} was — see that function's own doc
 * comment.
 * @param {import('contentful-management').PlainClientAPI} client
 * @param {string} target
 * @param {{ key: string; title: string; value: string; description: string }[]} entries
 * @returns {Promise<void>}
 * @throws {Error} if one or more existing drafts' content conflicts with the corresponding
 *   `entries` item — see above.
 */
export async function seedUiCopyEntries(client, target, entries) {
  log.section(`Seeding ${entries.length} uiCopy entries → environment: ${target}`);

  // Fetch all existing uiCopy entries across pages before duplicate checks.
  // contentful-management paginates at 1,000 — a single request may miss entries.
  const existing = [];
  let skip = 0;
  let total = Infinity;
  while (existing.length < total) {
    const page = await client.entry.getMany({
      environmentId: target,
      query: { content_type: 'uiCopy', limit: 1000, skip },
    });
    total = page.total;
    existing.push(...page.items);
    skip += page.items.length;
    if (page.items.length === 0) break; // guard against a zero-item page to prevent infinite loop
  }

  // Map from uiCopy key → full entry object so we can inspect sys.publishedVersion below.
  const existingEntryMap = new Map(
    existing.map((e) => [e.fields?.key?.['en'], e]).filter(([key]) => Boolean(key)),
  );

  let created = 0;
  let skipped = 0;
  let published = 0;
  const conflicts = [];

  for (const entry of entries) {
    const existingEntry = existingEntryMap.get(entry.key);
    if (existingEntry) {
      if (existingEntry.sys.publishedVersion == null) {
        // Entry exists as a draft — verify its content matches this script's data before
        // publishing it. A stale draft (an interrupted prior run, a manual edit in Contentful's
        // UI, or this script's `entries` array changing after the draft was left behind) must
        // not be silently published with content that disagrees with what this script says it
        // should be.
        const draftTitle = existingEntry.fields?.title?.['en'];
        const draftValue = existingEntry.fields?.value?.['en'];
        const draftDescription = existingEntry.fields?.description?.['en'];

        const mismatches = [];
        if (draftTitle !== entry.title) {
          mismatches.push(`title: expected "${entry.title}", found "${draftTitle}"`);
        }
        if (draftValue !== entry.value) {
          mismatches.push(`value: expected "${entry.value}", found "${draftValue}"`);
        }
        if (draftDescription !== entry.description) {
          mismatches.push(`description: expected "${entry.description}", found "${draftDescription}"`);
        }

        if (mismatches.length) {
          log.error(
            `${entry.key} — draft content does not match, refusing to publish (${mismatches.join('; ')})`,
          );
          conflicts.push(entry.key);
          continue;
        }

        // Entry exists as a draft whose content matches — publish it now so it is available to
        // the app.
        await client.entry.publish(
          { environmentId: target, entryId: existingEntry.sys.id },
          { sys: existingEntry.sys },
        );
        log.success(`${entry.key} — draft published`);
        published++;
      } else {
        log.skip(`${entry.key} — already published, skipping`);
        skipped++;
      }
      continue;
    }

    const created_entry = await client.entry.create(
      { environmentId: target, contentTypeId: 'uiCopy' },
      {
        fields: {
          title: { 'en': entry.title },
          key: { 'en': entry.key },
          value: { 'en': entry.value },
          description: { 'en': entry.description },
        },
      },
    );

    await client.entry.publish(
      { environmentId: target, entryId: created_entry.sys.id },
      { sys: created_entry.sys },
    );

    log.success(`${entry.key}`);
    created++;
  }

  log.section('Done');
  log.info(`Created and published: ${created}`);
  if (published) log.info(`Draft entries published: ${published}`);
  if (skipped) log.info(`Skipped (already published): ${skipped}`);
}

