// Throwaway local verification script for the _shared.mjs seedUiCopyEntries draft-mismatch fix.
// Not part of the repo — run from /tmp, deleted after use.
import { seedUiCopyEntries } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/scripts/contentful/setup/_shared.mjs';

function makeEntrySys(id, overrides = {}) {
  return { id, version: 1, publishedVersion: null, ...overrides };
}

async function scenario1_matchingDraftPublishes() {
  console.log('\n=== Scenario 1: matching draft still publishes (happy path, no regression) ===');
  const publishCalls = [];
  const existingEntries = [
    {
      sys: makeEntrySys('entry-a'),
      fields: {
        key: { en: 'drawer.close' },
        title: { en: 'Drawer — Close Button Label' },
        value: { en: 'Close' },
        description: { en: 'Accessible label for the close button.' },
      },
    },
  ];

  const client = {
    entry: {
      getMany: async () => ({ items: existingEntries, total: existingEntries.length }),
      publish: async (ids, body) => {
        publishCalls.push({ ids, body });
        return { sys: { ...body.sys, publishedVersion: body.sys.version + 1 } };
      },
      create: async () => {
        throw new Error('create should not be called in this scenario');
      },
    },
  };

  const entries = [
    {
      key: 'drawer.close',
      title: 'Drawer — Close Button Label',
      value: 'Close',
      description: 'Accessible label for the close button.',
    },
  ];

  let threw = null;
  try {
    await seedUiCopyEntries(client, 'dev', entries);
  } catch (err) {
    threw = err;
  }

  const pass = threw === null && publishCalls.length === 1 && publishCalls[0].ids.entryId === 'entry-a';
  console.log(pass ? 'PASS' : 'FAIL', {
    threw: threw?.message,
    publishCallCount: publishCalls.length,
  });
  return pass;
}

async function scenario2_mismatchedDraftRefusedAndThrows() {
  console.log('\n=== Scenario 2: mismatched draft is refused, no publish call, error thrown ===');
  const publishCalls = [];
  const errorLogs = [];
  const originalConsoleError = console.error;
  console.error = (...args) => {
    errorLogs.push(args.join(' '));
    originalConsoleError(...args);
  };

  const existingEntries = [
    {
      sys: makeEntrySys('entry-b'),
      fields: {
        key: { en: 'regional.locationPrompt.heading' },
        title: { en: 'STALE TITLE FROM MANUAL EDIT' },
        value: { en: "Looks like you're {inCountry}" },
        description: { en: 'Heading in the country mismatch prompt drawer.' },
      },
    },
  ];

  const client = {
    entry: {
      getMany: async () => ({ items: existingEntries, total: existingEntries.length }),
      publish: async (ids, body) => {
        publishCalls.push({ ids, body });
        return { sys: { ...body.sys, publishedVersion: body.sys.version + 1 } };
      },
      create: async () => {
        throw new Error('create should not be called in this scenario');
      },
    },
  };

  const entries = [
    {
      key: 'regional.locationPrompt.heading',
      title: 'Regional Prompt — Location Heading',
      value: "Looks like you're {inCountry}",
      description: 'Heading in the country mismatch prompt drawer.',
    },
  ];

  let threw = null;
  try {
    await seedUiCopyEntries(client, 'dev', entries);
  } catch (err) {
    threw = err;
  }

  console.error = originalConsoleError;

  const mentionsKey = errorLogs.some((l) => l.includes('regional.locationPrompt.heading'));
  const mentionsExpectedActual =
    errorLogs.some((l) => l.includes('STALE TITLE FROM MANUAL EDIT')) &&
    errorLogs.some((l) => l.includes('Regional Prompt — Location Heading'));
  const pass =
    publishCalls.length === 0 &&
    threw !== null &&
    threw.message.includes('regional.locationPrompt.heading') &&
    mentionsKey &&
    mentionsExpectedActual;

  console.log(pass ? 'PASS' : 'FAIL', {
    publishCallCount: publishCalls.length,
    threwMessage: threw?.message,
    errorLogs,
  });
  return pass;
}

async function scenario3_unrelatedEntryUnaffectedByConflict() {
  console.log('\n=== Scenario 3: unrelated entries in the same batch still processed despite a conflict ===');
  const publishCalls = [];
  const createCalls = [];

  const existingEntries = [
    {
      // conflicting draft
      sys: makeEntrySys('entry-conflict'),
      fields: {
        key: { en: 'conflict.key' },
        title: { en: 'Old Title' },
        value: { en: 'Old Value' },
        description: { en: 'Old Description' },
      },
    },
    {
      // matching draft — should still publish
      sys: makeEntrySys('entry-ok-draft'),
      fields: {
        key: { en: 'ok.draft.key' },
        title: { en: 'OK Title' },
        value: { en: 'OK Value' },
        description: { en: 'OK Description' },
      },
    },
    {
      // already published — should still skip
      sys: makeEntrySys('entry-already-published', { publishedVersion: 3 }),
      fields: {
        key: { en: 'already.published.key' },
        title: { en: 'Whatever' },
        value: { en: 'Whatever' },
        description: { en: 'Whatever' },
      },
    },
  ];

  const client = {
    entry: {
      getMany: async () => ({ items: existingEntries, total: existingEntries.length }),
      publish: async (ids, body) => {
        publishCalls.push(ids.entryId);
        return { sys: { ...body.sys, publishedVersion: body.sys.version + 1 } };
      },
      create: async (ids, body) => {
        createCalls.push(body.fields.key.en);
        return { sys: makeEntrySys('entry-new-' + body.fields.key.en) };
      },
    },
  };

  const entries = [
    {
      key: 'conflict.key',
      title: 'New Title',
      value: 'New Value',
      description: 'New Description',
    },
    {
      key: 'ok.draft.key',
      title: 'OK Title',
      value: 'OK Value',
      description: 'OK Description',
    },
    {
      key: 'already.published.key',
      title: 'Whatever',
      value: 'Whatever',
      description: 'Whatever',
    },
    {
      key: 'brand.new.key',
      title: 'Brand New',
      value: 'Brand New Value',
      description: 'Brand New Description',
    },
  ];

  let threw = null;
  try {
    await seedUiCopyEntries(client, 'dev', entries);
  } catch (err) {
    threw = err;
  }

  const pass =
    threw !== null &&
    threw.message.includes('conflict.key') &&
    publishCalls.includes('entry-ok-draft') &&
    !publishCalls.includes('entry-conflict') &&
    !publishCalls.includes('entry-already-published') &&
    createCalls.includes('brand.new.key');

  console.log(pass ? 'PASS' : 'FAIL', {
    threwMessage: threw?.message,
    publishCalls,
    createCalls,
  });
  return pass;
}

const results = await Promise.all([
  scenario1_matchingDraftPublishes(),
  scenario2_mismatchedDraftRefusedAndThrows(),
  scenario3_unrelatedEntryUnaffectedByConflict(),
]);

console.log('\n=== SUMMARY ===');
console.log('Scenario 1 (happy path, no regression):', results[0] ? 'PASS' : 'FAIL');
console.log('Scenario 2 (mismatch refused + throws):', results[1] ? 'PASS' : 'FAIL');
console.log('Scenario 3 (unrelated entries unaffected):', results[2] ? 'PASS' : 'FAIL');

if (results.every(Boolean)) {
  console.log('\nALL SCENARIOS PASSED');
  process.exit(0);
} else {
  console.log('\nSOME SCENARIOS FAILED');
  process.exit(1);
}
